import { useMemo, useState } from 'react';
import {
  JxCard,
  JxChip,
  JxChipGroup,
  JxStack,
  JxInline,
  JxText,
  JxHeading,
  JxDivider,
  JxProgressCircle,
  JxBadge,
  JxButton,
  JxEmptyState,
  JxPagination,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'atRisk' | 'overBudget' | 'completed';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  atRisk: 'Под угрозой',
  overBudget: 'Превышен бюджет',
  completed: 'Завершён',
};

const STATUS_TONE: Record<ProjectStatus, 'neutral' | 'success' | 'warning' | 'danger'> = {
  active: 'success',
  atRisk: 'warning',
  overBudget: 'danger',
  completed: 'neutral',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Редизайн личного кабинета', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Миграция на новый биллинг', quotaPercent: 88, status: 'atRisk' },
  { id: 'p3', name: 'Мобильное приложение v2', quotaPercent: 15, status: 'active' },
  { id: 'p4', name: 'Интеграция с CRM', quotaPercent: 104, status: 'overBudget' },
  { id: 'p5', name: 'Аналитическая панель', quotaPercent: 100, status: 'completed' },
  { id: 'p6', name: 'Оптимизация склада', quotaPercent: 67, status: 'active' },
  { id: 'p7', name: 'Служба поддержки бот', quotaPercent: 95, status: 'atRisk' },
  { id: 'p8', name: 'Архив документов', quotaPercent: 100, status: 'completed' },
  { id: 'p9', name: 'Платёжный шлюз', quotaPercent: 112, status: 'overBudget' },
  { id: 'p10', name: 'Внутренний портал', quotaPercent: 30, status: 'active' },
  { id: 'p11', name: 'Рекомендательная система', quotaPercent: 74, status: 'atRisk' },
  { id: 'p12', name: 'Обновление дизайн-системы', quotaPercent: 100, status: 'completed' },
];

const ALL_STATUSES = Object.keys(STATUS_LABEL) as ProjectStatus[];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeFilters, setActiveFilters] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeFilters.includes(project.status)),
    [activeFilters]
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);

  const pageProjects = useMemo(
    () => filteredProjects.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [filteredProjects, safePage]
  );

  function removeFilter(status: ProjectStatus) {
    setActiveFilters((prev) => prev.filter((item) => item !== status));
    setPage(1);
  }

  function resetFilters() {
    setActiveFilters(ALL_STATUSES);
    setPage(1);
  }

  function handlePageChange(nextPage: number) {
    setPage(nextPage);
  }

  return (
    <JxCard padding="lg">
      <JxStack gap="lg">
        <JxStack gap="xs">
          <JxHeading level={2} size="md">
            Расход по проектам
          </JxHeading>
          <JxText size="sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
            Заполненность квоты и статус по каждому проекту
          </JxText>
        </JxStack>

        <JxChipGroup wrap>
          {activeFilters.length === 0 ? (
            <JxText size="sm" style={{ color: 'var(--jx-color-text-secondary)' }}>
              Все фильтры сняты
            </JxText>
          ) : (
            activeFilters.map((status) => (
              <JxChip
                key={status}
                tone={STATUS_TONE[status]}
                removable
                onRemove={() => removeFilter(status)}
              >
                {STATUS_LABEL[status]}
              </JxChip>
            ))
          )}
        </JxChipGroup>

        <JxDivider />

        {pageProjects.length === 0 ? (
          <JxEmptyState
            title="Ничего не найдено"
            description="По выбранным фильтрам нет проектов. Сбросьте фильтры, чтобы увидеть все проекты."
          >
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          </JxEmptyState>
        ) : (
          <JxStack gap="sm">
            {pageProjects.map((project) => (
              <JxCard key={project.id} padding="md" variant="outlined">
                <JxInline justify="space-between" align="center" gap="md">
                  <JxText weight="medium">{project.name}</JxText>
                  <JxInline align="center" gap="md">
                    <JxProgressCircle
                      value={Math.min(project.quotaPercent, 100)}
                      size="sm"
                      tone={STATUS_TONE[project.status]}
                      label={`${project.quotaPercent}%`}
                    />
                    <JxBadge tone={STATUS_TONE[project.status]}>
                      {STATUS_LABEL[project.status]}
                    </JxBadge>
                  </JxInline>
                </JxInline>
              </JxCard>
            ))}
          </JxStack>
        )}

        {filteredProjects.length > 0 && (
          <JxPagination
            page={safePage}
            pageCount={pageCount}
            onPageChange={handlePageChange}
          />
        )}
      </JxStack>
    </JxCard>
  );
}

